def input_features(self, seq: torch.Tensor) -> torch.Tensor:
    # Count only earlier matching items within the available causal window.
    matches = seq.unsqueeze(2).eq(seq.unsqueeze(1))
    earlier_counts = torch.tril(matches, diagonal=-1).sum(dim=-1, dtype=torch.float32)
    scales = torch.rsqrt(1.0 + earlier_counts)
    scales = scales * seq.ne(0).to(scales.dtype)
    emb = self.item_emb(seq)
    return self.dropout(emb * scales.to(emb.dtype).unsqueeze(-1))

def encode(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.input_features(seq)
